const finishDelivery = `-- name: FinishDelivery :execrows
UPDATE notification_deliveries
SET status = ?1,
    next_attempt_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now', CAST(?2 AS TEXT)),
    last_error = ?3,
    sent_at = CASE WHEN ?1 = 'sent' THEN strftime('%Y-%m-%dT%H:%M:%fZ', 'now') ELSE sent_at END,
    reserved_by = NULL,
    reserved_until = NULL
WHERE id = ?4 AND reserved_token = ?5 AND status IN ('pending', 'attempting')
`

type FinishDeliveryParams struct {
	Status        string         `json:"status"`
	RetryModifier string         `json:"retry_modifier"`
	LastError     sql.NullString `json:"last_error"`
	ID            int64          `json:"id"`
	ReservedToken int64          `json:"reserved_token"`
}

// Writes one attempt's outcome while the reservation is current. A pending
// outcome is due again after retry_modifier.
func (q *Queries) FinishDelivery(ctx context.Context, arg FinishDeliveryParams) (int64, error) {
	result, err := q.exec(ctx, q.finishDeliveryStmt, finishDelivery,
		arg.Status,
		arg.RetryModifier,
		arg.LastError,
		arg.ID,
		arg.ReservedToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const finishJob = `-- name: FinishJob :execrows
UPDATE jobs
SET next_run_at = CASE
        WHEN schedule_kind = ?1
         AND schedule_expr = ?2
         AND timezone = ?3
        THEN CAST(?4 AS TEXT)
        ELSE next_run_at
    END,
    last_status = ?5,
    last_error = ?6,
    last_finished_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
    lease_owner = NULL,
    lease_expires_at = NULL,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id = ?7 AND lease_token = ?8
`

type FinishJobParams struct {
	ScheduleKind string         `json:"schedule_kind"`
	ScheduleExpr string         `json:"schedule_expr"`
	Timezone     string         `json:"timezone"`
	NextRunAt    string         `json:"next_run_at"`
	LastStatus   sql.NullString `json:"last_status"`
	LastError    sql.NullString `json:"last_error"`
	ID           int64          `json:"id"`
	LeaseToken   int64          `json:"lease_token"`
}

// The next run applies only while the job keeps the schedule the run used,
// so a schedule change made during the run is not overwritten.
func (q *Queries) FinishJob(ctx context.Context, arg FinishJobParams) (int64, error) {
	result, err := q.exec(ctx, q.finishJobStmt, finishJob,
		arg.ScheduleKind,
		arg.ScheduleExpr,
		arg.Timezone,
		arg.NextRunAt,
		arg.LastStatus,
		arg.LastError,
		arg.ID,
		arg.LeaseToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

