const queryStatsSummary = `-- name: QueryStatsSummary :one

SELECT
    CAST(COALESCE(SUM(CASE WHEN qsd.bucket_date >= ?1 THEN qsd.query_count ELSE 0 END), 0) AS INTEGER) AS query_count,
    CAST(COALESCE(SUM(CASE WHEN qsd.bucket_date >= ?1 THEN qsd.total_duration_ms ELSE 0 END), 0) AS INTEGER) AS total_duration_ms,
    CAST(COUNT(DISTINCT CASE WHEN qsd.bucket_date >= ?1 THEN qsd.user_id END) AS INTEGER) AS active_users,
    CAST(COUNT(DISTINCT CASE WHEN qsd.bucket_date >= ?1 THEN qsd.source_id END) AS INTEGER) AS active_sources,
    CAST(COALESCE(SUM(CASE WHEN qsd.bucket_date < ?1 THEN qsd.query_count ELSE 0 END), 0) AS INTEGER) AS prior_query_count,
    CAST(COALESCE(SUM(CASE WHEN qsd.bucket_date < ?1 THEN qsd.total_duration_ms ELSE 0 END), 0) AS INTEGER) AS prior_total_duration_ms,
    CAST(COUNT(DISTINCT CASE WHEN qsd.bucket_date < ?1 THEN qsd.user_id END) AS INTEGER) AS prior_active_users,
    CAST(COUNT(DISTINCT CASE WHEN qsd.bucket_date < ?1 THEN qsd.source_id END) AS INTEGER) AS prior_active_sources
FROM query_stats_daily qsd
LEFT JOIN users u ON u.id = qsd.user_id
WHERE qsd.bucket_date >= ?2 AND qsd.bucket_date <= ?3
  AND (CAST(?4 AS TEXT) = '' OR u.account_type = ?4)
  AND (CAST(?5 AS INTEGER) = 0 OR qsd.source_id = ?5)
  AND (CAST(?6 AS INTEGER) = 0 OR qsd.user_id = ?6)
`

type QueryStatsSummaryParams struct {
	Since       string `json:"since"`
	PriorSince  string `json:"prior_since"`
	Until       string `json:"until"`
	AccountType string `json:"account_type"`
	SourceID    int64  `json:"source_id"`
	UserID      int64  `json:"user_id"`
}

type QueryStatsSummaryRow struct {
	QueryCount           int64 `json:"query_count"`
	TotalDurationMs      int64 `json:"total_duration_ms"`
	ActiveUsers          int64 `json:"active_users"`
	ActiveSources        int64 `json:"active_sources"`
	PriorQueryCount      int64 `json:"prior_query_count"`
	PriorTotalDurationMs int64 `json:"prior_total_duration_ms"`
	PriorActiveUsers     int64 `json:"prior_active_users"`
	PriorActiveSources   int64 `json:"prior_active_sources"`
}

// The Query Activity reads below take one window from prior_since to until,
// both inclusive, and count a row as current when bucket_date >= since. An
// empty account_type and a zero source_id or user_id select everything. A
// user row that is gone has no account type, so its queries count only when
// account_type is empty.
func (q *Queries) QueryStatsSummary(ctx context.Context, arg QueryStatsSummaryParams) (QueryStatsSummaryRow, error) {
	row := q.queryRow(ctx, q.queryStatsSummaryStmt, queryStatsSummary,
		arg.Since,
		arg.PriorSince,
		arg.Until,
		arg.AccountType,
		arg.SourceID,
		arg.UserID,
	)
	var i QueryStatsSummaryRow
	err := row.Scan(
		&i.QueryCount,
		&i.TotalDurationMs,
		&i.ActiveUsers,
		&i.ActiveSources,
		&i.PriorQueryCount,
		&i.PriorTotalDurationMs,
		&i.PriorActiveUsers,
		&i.PriorActiveSources,
	)
	return i, err
}

